    async function save({ approve = false } = {}) {
        const generatedFileNo = createAutoGeneratedFileNo();
        const file_no = toText(formData.new_file_no || formData.old_file_no || formData.file_no) || generatedFileNo;
        const name = toText(formData.management_corporation_name || formData.name);
        if (!name) return showToast('Name is required', 'error');

        const payload = {
            ...formData,
            ...formChecklistData,
            user_name: currentUser?.name || currentUser?.username || 'System',
            file_no,
            name,
            management_corporation_name: name,
            old_file_no: toText(formData.old_file_no),
            new_file_no: toText(formData.new_file_no),
            residential_units: toIntOrNull(formData.residential_units),
            residential: toIntOrNull(formData.residential_units),
            non_residential: toIntOrNull(formData.non_residential_units),
            service_units: toIntOrNull(formData.service_units),
            non_res_shops: toIntOrNull(formData.non_res_shops),
            non_res_office: toIntOrNull(formData.non_res_office),
            non_res_hotel: toIntOrNull(formData.non_res_hotel),
            council_members: serializeCouncilMembers(formData.council_members),
            year: formData.year === '' ? null : deriveYear(formData.year),
            status: approve ? 'Active' : (editingId ? (formData.status || 'New') : 'New'),
            // Auto-calculated fee breakdown (always up-to-date from useMemo)
            category: feeBreakdown.categoryLabel || formData.category,
            fee_rate_per_unit: feeBreakdown.rate,
            fee_amount: feeBreakdown.fee,
            sscl_amount: feeBreakdown.sscl,
            vat_amount: feeBreakdown.vat,
            total_amount: feeBreakdown.total,
            units: totalParcels || formData.units,
            non_residential_units: (parseInt(formData.non_res_shops) || 0) + (parseInt(formData.non_res_office) || 0) + (parseInt(formData.non_res_hotel) || 0) || formData.non_residential_units,
            ...(auditUserLabel ? { created_by: auditUserLabel, modified_by: auditUserLabel } : {}),
        };

        try {
            const API_BASE = import.meta.env.VITE_API_URL ?? '/api';
            if (editingId) {
                const r = await fetch(`${API_BASE}/mc/${editingId}`, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload),
                });
                const body = await r.json().catch(() => ({}));
                if (!r.ok) throw new Error(body.error || 'Update failed');
                showToast(approve ? 'MC approved & activated -' : 'MC updated successfully');

                if (payload.status === 'Pending' && !approve) {
                    try {
                        const today = new Date().toLocaleDateString('en-GB');
                        const fileNo = payload.new_file_no || payload.old_file_no || body?.mc?.new_file_no || body?.mc?.old_file_no || '-';
                        let pendingCountStr = '';
                        try {
                            const pd = await fetchMCsFiltered({ status: 'Pending', limit: 1 });
                            if (pd && typeof pd.total === 'number') pendingCountStr = `\nTotal Pending: ${pd.total}`;
                        } catch (e) { }
                        const created = await createNotification({
                            type: 'info',
                            title: 'MC Updated to Pending - Approval Required',
                            message: `File No: ${fileNo} | Name: "${name}" | Updated: ${today}. Pending AGM approval.${pendingCountStr}`,
                            target_role: 'AGM',
                            link: `mc:pending`,
                        });
                        try {
                            const detail = created?.notification || created;
                            if (detail) window.dispatchEvent(new CustomEvent('cma:new-notification', { detail }));
                        } catch (evErr) { }
                    } catch (err) { }
                } else if (approve) {
                    try {
                        const today = new Date().toLocaleDateString('en-GB');
                        const fileNo = payload.new_file_no || payload.old_file_no || body?.mc?.new_file_no || body?.mc?.old_file_no || '-';
                        const approvedBy = currentUser?.name || currentUser?.username || 'AGM';
                        const created = await createNotification({
                            type: 'success',
                            title: 'MC Approved',
                            message: `File No: ${fileNo} | Name: "${name}" | Approved: ${today} by ${approvedBy}.`,
                            target_role: null, // broadcast to all
                            link: `mc:${editingId}`,
                        });
                        try {
                            const detail = created?.notification || created;
                            if (detail) {
                                window.dispatchEvent(new CustomEvent('cma:new-notification', { detail }));
                                window.dispatchEvent(new CustomEvent('cma:refresh-mc'));
                            }
                        } catch (evErr) { }
                    } catch (err) { }
                }

                // - Immediately update local state with the actual server response -
                // body.mc is the saved record returned by the backend PATCH endpoint.
                // Fallback to merging the payload so the UI is never stale.
                // NOTE: backend PATCH returns the full record directly as `body` (not body.mc).
                const savedRecord = (body && body.id) ? body : { ...payload, id: editingId };
                setMcs((prev) => prev.map((item) => (item.id === editingId ? { ...item, ...savedRecord } : item)));
                if (viewRecord?.id === editingId) {
                    setViewRecord((prev) => ({ ...prev, ...savedRecord }));
                }


                setModalOpen(false);
                load(); // refresh list in background - don't await so modal closes instantly
                return; // early return so we don't hit the generic setModalOpen below

            } else {
                const createdMc = await createMC(payload);
                showToast(approve ? 'MC created & activated -' : 'MC created successfully');

                if (!approve) {
                    try {
                        const today = new Date().toLocaleDateString('en-GB');
                        const fileNo = payload.new_file_no || payload.old_file_no || createdMc?.new_file_no || createdMc?.old_file_no || '-';

                        let pendingCountStr = '';
                        try {
                            const pd = await fetchMCsFiltered({ status: 'Pending', limit: 1 });
                            if (pd && typeof pd.total === 'number') pendingCountStr = `\nTotal Pending: ${pd.total}`;
                        } catch (e) { }

                        const created = await createNotification({
                            type: 'info',
                            title: 'New MC Registration - Approval Required',
                            message: `File No: ${fileNo} | Name: "${name}" | Submitted: ${today}. Pending AGM approval.${pendingCountStr}`,
                            target_role: 'AGM',
                            link: `mc:pending`,
                        });
                        try {
                            const detail = created?.notification || created;
                            if (detail) window.dispatchEvent(new CustomEvent('cma:new-notification', { detail }));
                        } catch (evErr) { }
                    } catch (err) {
                        console.error('Failed to notify AGM:', err);
                    }
                } else {
                    try {
                        const today = new Date().toLocaleDateString('en-GB');
                        const fileNo = payload.new_file_no || payload.old_file_no || createdMc?.new_file_no || createdMc?.old_file_no || '-';
                        const approvedBy = currentUser?.name || currentUser?.username || 'AGM';
                        const created = await createNotification({
                            type: 'success',
                            title: 'MC Approved',
                            message: `File No: ${fileNo} | Name: "${name}" | Approved: ${today} by ${approvedBy}.`,
                            target_role: null, // broadcast
                            link: `mc:${createdMc?.id}`,
                        });
                        try {
                            const detail = created?.notification || created;
                            if (detail) {
                                window.dispatchEvent(new CustomEvent('cma:new-notification', { detail }));
                                window.dispatchEvent(new CustomEvent('cma:refresh-mc'));
                            }
                        } catch (evErr) { }
                    } catch (err) { }
                }
            }
            setModalOpen(false);
            load(); // refresh list after new create

        } catch (e) {
            showToast(e.message || 'Save failed', 'error');
        }
    }

    async function remove(id) {
        const confirmed = await confirm({
            title: 'Delete MC record',
            message: 'Delete this MC record? This action cannot be undone.',
            confirmLabel: 'Delete',
            cancelLabel: 'Cancel',
        });
        if (!confirmed) return;
        try {
            const API_BASE = import.meta.env.VITE_API_URL ?? '/api';
            const r = await fetch(`${API_BASE}/mc/${id}`, { method: 'DELETE' });
            const body = await r.json().catch(() => ({}));
            if (!r.ok) throw new Error(body.error || 'Delete failed');
            showToast('Record deleted', 'error');
            load();
        } catch (e) {
            showToast(e.message || 'Delete failed', 'error');
        }
    }

