    async function patchMC(id, payload) {
        const API_BASE = import.meta.env.VITE_API_URL ?? '/api';
        const r = await fetch(`${API_BASE}/mc/${id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ user_name: currentUser?.name || currentUser?.username || 'System', ...payload }),
        });
        const body = await r.json().catch(() => ({}));
        if (!r.ok) throw new Error(body.error || 'Update failed');
        return body;
    }

    async function handleChecklistSave(checkData) {
        try {
            const updated = await patchMC(checklistRecord.id, checkData);
            setMcs((prev) => prev.map((item) => (item.id === updated.id ? { ...item, ...updated } : item)));
            setChecklistRecord((prev) => (prev && prev.id === updated.id ? { ...prev, ...updated } : prev));
            if (viewRecord?.id === updated.id) {
                setViewRecord((prev) => (prev ? { ...prev, ...updated } : prev));
            }
            showToast('Checklist progress saved -');

            // Notify AGM via popup notification (DB-backed, role-targeted)
            try {
                const fileNo = updated.new_file_no || updated.old_file_no || checklistRecord.new_file_no || checklistRecord.old_file_no || '-';
                const mcName = updated.management_corporation_name || updated.name || checklistRecord.management_corporation_name || checklistRecord.name || '-';
                const today = new Date().toLocaleDateString('en-GB');
                const savedBy = currentUser?.name || currentUser?.username || 'System';

                let pendingCountStr = '';
                try {
                    const pd = await fetchMCsFiltered({ status: 'Pending', limit: 1 });
                    if (pd && typeof pd.total === 'number') pendingCountStr = `\nTotal Pending: ${pd.total}`;
                } catch (e) { }

                const created = await createNotification({
                    type: 'info',
                    title: 'MC Checklist Updated - Approval Needed',
                    message: `File No: ${fileNo} | Name: "${mcName}" | Updated: ${today} by ${savedBy}. Awaiting AGM approval.${pendingCountStr}`,
                    target_role: 'AGM',
                    link: `mc:pending`,
                });
                try {
                    const detail = created?.notification || created;
                    if (detail) window.dispatchEvent(new CustomEvent('cma:new-notification', { detail }));
                } catch (evErr) { /* non-fatal */ }
            } catch (err) {
                console.error('Failed to send checklist notification to AGM:', err);
            }
        } catch (e) {
            showToast(e.message || 'Save failed', 'error');
        }
    }

    async function handleChecklistApprove(checkData) {
        try {
            const normalized = normalizeChecklistPayload(checkData);
            const updated = await patchMC(checklistRecord.id, { ...normalized, status: 'Active' });
            setMcs((prev) => prev.map((item) => (item.id === updated.id ? { ...item, ...updated } : item)));
            setChecklistRecord((prev) => (prev && prev.id === updated.id ? { ...prev, ...updated } : prev));
            if (viewRecord?.id === updated.id) {
                setViewRecord((prev) => (prev ? { ...prev, ...updated } : prev));
            }
            showToast('MC Approved & set to Active -');
            setChecklistModalOpen(false);

            // Broadcast approval notification to ALL users with full details
            try {
                const fileNo = updated.new_file_no || updated.old_file_no || checklistRecord.new_file_no || checklistRecord.old_file_no || '-';
                const mcName = updated.management_corporation_name || updated.name || checklistRecord.management_corporation_name || checklistRecord.name || '-';
                const today = new Date().toLocaleDateString('en-GB');
                const approvedBy = currentUser?.name || currentUser?.username || 'AGM';
                const created = await createNotification({
                    type: 'success',
                    title: 'MC Approved',
                    message: `File No: ${fileNo} | Name: "${mcName}" | Approved: ${today} by ${approvedBy}.`,
                    target_role: null, // broadcast to all users
                    link: `mc:${checklistRecord.id}`,
                });
                // Dispatch immediately to all open tabs/windows
                try {
                    const detail = created?.notification || created;
                    if (detail) {
                        window.dispatchEvent(new CustomEvent('cma:new-notification', { detail }));
                        window.dispatchEvent(new CustomEvent('cma:refresh-mc'));
                    }
                } catch (evErr) { /* non-fatal */ }
            } catch (e) {
                console.error('Failed to broadcast approval notification:', e);
            }

            // Reload the MC list to reflect the status change
            load();
        } catch (e) {
            showToast(e.message || 'Approve failed', 'error');
        }
    }

    async function handleChecklistReject(checkData) {
        try {
            const updated = await patchMC(checklistRecord.id, { ...checkData, status: 'Non Active' });
            setMcs((prev) => prev.map((item) => (item.id === updated.id ? { ...item, ...updated } : item)));
            setChecklistRecord((prev) => (prev && prev.id === updated.id ? { ...prev, ...updated } : prev));
            if (viewRecord?.id === updated.id) {
                setViewRecord((prev) => (prev ? { ...prev, ...updated } : prev));
            }
            showToast('MC Rejected & set to Non Active', 'error');
            setChecklistModalOpen(false);
        } catch (e) {
            showToast(e.message || 'Reject failed', 'error');
        }
    }

